from fractions import Fraction as F
import json
rows=[('A',5,(0,0,0,1)),('A',6,(1,0,1,0)),('B',11,(0,0,0,1)),('B',5,(0,1,1,0)),('C',6,(0,1,0,1)),('C',4,(1,0,1,1)),('D',6,(0,0,1,0)),('D',8,(1,1,0,0))]
names='TUVW'
cost=[F(1),F(1),F(17,10),F(21,10)]
loss=[[0,7,10,21],[7,0,22,11],[19,13,0,19],[12,6,13,0]]
def stop(ids):
    w=sum(rows[i][1] for i in ids)
    return min((F(sum(rows[i][1]*loss[a]['ABCD'.index(rows[i][0])] for i in ids),w),'ABCD'[a]) for a in range(4))
def solve(ids,available,budget):
    choices=[stop(ids)]
    if budget:
        for t in available:
            choices.append((buy(ids,available,budget,t),names[t]))
    return min(choices)
def buy(ids,available,budget,t):
    total=sum(rows[i][1] for i in ids)
    value=cost[t]
    for outcome in (0,1):
        subset=tuple(i for i in ids if rows[i][2][t]==outcome)
        if subset:
            value+=F(sum(rows[i][1] for i in subset),total)*solve(subset,tuple(x for x in available if x!=t),budget-1)[0]
    return value
ids=tuple(range(8)); available=tuple(range(4))
values={'STOP':stop(ids)[0]}
values.update({names[t]:buy(ids,available,2,t) for t in available})
value,action=solve(ids,available,2)
next_actions={}
if action in names:
    t=names.index(action)
    for outcome in (0,1):
        subset=tuple(i for i in ids if rows[i][2][t]==outcome)
        next_actions[str(outcome)]=solve(subset,tuple(x for x in available if x!=t),1)[1] if subset else 'IMPOSSIBLE'
result={'first':action,'first_losses':{k:float(v) for k,v in values.items()},'next':next_actions}
payload=json.dumps(result)
recovered=json.loads(payload)
assert set(recovered)=={'first','first_losses','next'}
assert set(recovered['first_losses'])=={'STOP','T','U','V','W'}
assert recovered['first_losses'][action]==min(recovered['first_losses'].values())
print(payload)
print('Exact values:', {k:str(v) for k,v in values.items()})
print('Branch decisions:',next_actions)

